images=[Image.open(root/name).convert('RGBA') for name in ['reference.png','candidate.png']]
for col,(name,im) in enumerate(zip(['REFERENCE','CANDIDATE'],images)):
    x=20+col*420
    d.text((x,10),name,fill='black'); d.text((x,32),'Native 32 x 32',fill='black')
    board.paste(im,(x,52),im)
    d.text((x,99),'12x nearest; light background',fill='black')
    board.paste(im.resize((384,384),Image.Resampling.NEAREST),(x,118),im.resize((384,384),Image.Resampling.NEAREST))
    d.text((x,518),'Flat alpha silhouette, 8x',fill='black')
    mask=Image.new('RGBA',im.size,'#111111'); mask.putalpha(im.getchannel('A'))
    board.paste(mask.resize((256,256),Image.Resampling.NEAREST),(x,538),mask.resize((256,256),Image.Resampling.NEAREST))
    d.text((x,812),'Native on light / dark / busy test grounds',fill='black')
    for j,bg in enumerate(['#f0eee7','#121826',None]):
        bgim=Image.new('RGBA',(64,64),bg or '#647254')
        if bg is None:
            bd=ImageDraw.Draw(bgim)
            for yy in range(0,64,4):
                for xx in range(0,64,4):
                    if (xx//4+yy//4)%2: bd.rectangle((xx,yy,xx+3,yy+3),fill='#92926d')
        bgim.alpha_composite(im,(16,16)); board.paste(bgim.convert('RGB'),(x+j*90,840))
board.save(out/'comparison.png')
metadata={}
for name,im in zip(['reference.png','candidate.png'],images):
    counts={}
    for p in list(im.getdata()):
        if p[3]:
            key='#%02x%02x%02x'%p[:3]; counts[key]=counts.get(key,0)+1
    metadata[name]={'sha256':hashlib.sha256((root/name).read_bytes()).hexdigest(),'visible_color_counts':counts,'alpha_values':sorted(set(im.getchannel('A').getdata()))}
(out/'pixel-observations.json').write_text(json.dumps(metadata,indent=2)+'\\n',encoding='utf-8')
print(json.dumps(metadata))
